//! `cargo run -p ludion-shader-bindgen` — reflect the repo's WGSL shaders and (re)write the
//! renderer's committed `crates/ludion-renderer/src/shader_gen.rs` (Plan/shader-bindgen.md Wave 3).
//!
//! With no arguments it rewrites the file only when the bytes differ. With `--check` it never
//! writes: it compares the freshly-generated bytes against the committed file and exits nonzero when
//! they disagree — the drift gate CI and `scripts/check.mjs` call (decision 12: CI never mutates).

use std::path::Path;
use std::process::ExitCode;

use ludion_shader_bindgen::{check_atomic_free, check_unfilterable, emit, load_units, reflect};

const OUTPUT: &str = "crates/ludion-renderer/src/shader_gen.rs";

fn main() -> ExitCode {
    let check = std::env::args().skip(1).any(|a| a == "--check");

    // `CARGO_MANIFEST_DIR/../..` is the workspace root (this crate lives at `crates/<name>`).
    let workspace = Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(Path::parent)
        .expect("crate is two levels below the workspace root")
        .to_path_buf();

    let units = match load_units(&workspace) {
        Ok(u) => u,
        Err(e) => {
            eprintln!("shader-bindgen: {e}");
            return ExitCode::FAILURE;
        }
    };

    let reflection = match reflect(&units) {
        Ok(r) => r,
        Err(e) => {
            eprintln!("shader-bindgen: reflection failed: {e}");
            return ExitCode::FAILURE;
        }
    };
    if let Err(e) = check_unfilterable(&reflection) {
        eprintln!("shader-bindgen: {e}");
        return ExitCode::FAILURE;
    }
    if let Err(e) = check_atomic_free(&reflection) {
        eprintln!("shader-bindgen: {e}");
        return ExitCode::FAILURE;
    }
    let generated = emit(&reflection);

    let out_path = workspace.join(OUTPUT);
    let committed = std::fs::read_to_string(&out_path).unwrap_or_default();

    if check {
        if committed == generated {
            println!("shader-bindgen: {OUTPUT} is up to date");
            ExitCode::SUCCESS
        } else {
            eprintln!(
                "shader-bindgen: {OUTPUT} is STALE — it no longer matches the WGSL.\n\
                 Regenerate it with `cargo run -p ludion-shader-bindgen` and commit the result."
            );
            ExitCode::FAILURE
        }
    } else if committed == generated {
        println!("shader-bindgen: {OUTPUT} already up to date");
        ExitCode::SUCCESS
    } else {
        if let Err(e) = ludion_core::atomic::write_atomic(&out_path, generated.as_bytes()) {
            eprintln!("shader-bindgen: failed to write {OUTPUT}: {e}");
            return ExitCode::FAILURE;
        }
        println!("shader-bindgen: wrote {OUTPUT}");
        ExitCode::SUCCESS
    }
}
